#include "matter_endpoint_config.h"\n #include "led_driver.h"\n #include "nvs_storage.h"\n #include < esp_log.h>\n #include < app / server / Server.h>\n\nusing namespace esp_matter;\nusing namespace esp_matter::cluster;\nusing namespace esp_matter::endpoint;\n\nstatic const char *TAG = "MATTER_EP";\n\n // Helper to convert HSV (from Matter ColorControl) to RGB\nstatic void hsv_to_rgb(uint8_t h, uint8_t s, uint8_t v, uint8_t *r, uint8_t *g, uint8_t *b) {\n    float h_f = h * (360.0f / 254.0f);\n    float s_f = s / 254.0f;\n    float v_f = v / 254.0f;\n\n    int i = (int)(h_f / 60.0f);\n    float f = (h_f / 60.0f) - i;\n    float p = v_f * (1.0f - s_f);\n    float q = v_f * (1.0f - s_f * f);\n    float t = v_f * (1.0f - s_f * (1.0f - f));\n\n    float rf = 0, gf = 0, bf = 0;\n    switch (i % 6) {\n        case 0: rf = v_f, gf = t, bf = p; break;\n        case 1: rf = q, gf = v_f, bf = p; break;\n        case 2: rf = p, gf = v_f, bf = t; break;\n        case 3: rf = p, gf = q, bf = v_f; break;\n        case 4: rf = t, gf = p, bf = v_f; break;\n        case 5: rf = v_f, gf = p, bf = q; break;\n    }\n    *r = (uint8_t)(rf * 255);\n    *g = (uint8_t)(gf * 255);\n    *b = (uint8_t)(bf * 255);\n}\n\nesp_err_t matter_endpoint_attribute_update_cb(\n    attribute::callback_type_t type, uint16_t endpoint_id, uint32_t cluster_id,\n    uint32_t attribute_id, esp_matter_attr_val_t *val, void *priv_data) {\n\n    if (type != attribute::PRE_UPDATE) return ESP_OK;\n\n    nvs_storage_state_t state;\n    nvs_storage_load_state(&state); // Grab current to avoid full overwrite\n    bool changed = false;\n\n    if (cluster_id == on_off::Id && attribute_id == on_off::attribute::on_off::Id) {\n        bool is_on = val->val.b;\n        ESP_LOGI(TAG, "Matter Command: OnOff=%d", is_on);\n        state.is_on = is_on;\n        if (is_on) {\n            led_driver_set_brightness(state.brightness > 0 ? state.brightness : 255);\n        } else {\n            led_driver_set_brightness(0);\n        }\n        changed = true;\n    }\n    else if (cluster_id == level_control::Id && attribute_id == level_control::attribute::current_level::Id) {\n        uint8_t level = val->val.u8;\n        ESP_LOGI(TAG, "Matter Command: LevelControl=%d", level);\n        state.brightness = level;\n        led_driver_set_brightness(level);\n        changed = true;\n    }\n    else if (cluster_id == color_control::Id) {\n        static uint8_t curr_h = 0, curr_s = 0;\n        if (attribute_id == color_control::attribute::current_hue::Id) curr_h = val->val.u8;\n        if (attribute_id == color_control::attribute::current_saturation::Id) curr_s = val->val.u8;\n\n        uint8_t r, g, b;\n        hsv_to_rgb(curr_h, curr_s, 254, &r, &g, &b);\n        ESP_LOGI(TAG, "Matter Command: Color H=%d, S=%d -> R=%d,G=%d,B=%d", curr_h, curr_s, r, g, b);\n        \n        state.r = r; state.g = g; state.b = b;\n        led_driver_set_rgb(r, g, b);\n        changed = true;\n    }\n\n    if (changed) {\n        nvs_storage_save_state(&state);\n    }\n\n    return ESP_OK;\n}\n\nesp_err_t matter_endpoint_identification_cb(identification::callback_type_t type,\n    uint16_t endpoint_id, uint8_t effect_id, uint8_t effect_variant, void *priv_data) {\n    ESP_LOGI(TAG, "Identification trigger (Identify cluster)");\n    // E.g. Blink LED green to identify the bulb during commissioning\n    return ESP_OK;\n}\n\nvoid matter_endpoint_event_cb(const ChipDeviceEvent *event, intptr_t arg) {\n    // Background thread hooks for fabric joining, network provisioning etc.\n}\n\nvoid matter_endpoint_setup(node_t *node) {\n    ESP_LOGI(TAG, "Setting up standard Matter endpoint for Extended Color Light...");\n    \n    extended_color_light::config_t light_config;\n    endpoint_t *light_ep = extended_color_light::create(node, &light_config, ENDPOINT_FLAG_NONE, NULL);\n    \n    // Enable OTA Requestor cluster on root endpoint\n    ota_requestor::config_t ota_req_config;\n    cluster::ota_requestor::create(esp_matter::endpoint::get(node, 0), &ota_req_config, CLUSTER_FLAG_CLIENT);\n    \n    // Enable Diagnostics (for RSSI reporting)\n    diagnostics_network_wifi::config_t diag_config;\n    cluster::diagnostics_network_wifi::create(esp_matter::endpoint::get(node, 0), &diag_config, CLUSTER_FLAG_SERVER);\n\n    ESP_LOGI(TAG, "Matter endpoint configured successfully.");\n}\n
